nextflow_process {

    name "Test Process MINIMAC4_IMPUTE"
    script "../main.nf"
    process "MINIMAC4_IMPUTE"

    tag "modules"
    tag "modules_nfcore"
    tag "minimac4"
    tag "minimac4/impute"
    tag "minimac4/compressref"

    config "./nextflow.config"

    setup {
        run("MINIMAC4_COMPRESSREF") {
            script "../../compressref/main.nf"
            process {
                """
                input[0] = [
                    [ id:'input' ],
                    file(params.modules_testdata_base_path + "genomics/homo_sapiens/popgen/1000GP.chr22.vcf.gz", checkIfExists: true),
                    file(params.modules_testdata_base_path + "genomics/homo_sapiens/popgen/1000GP.chr22.vcf.gz.csi", checkIfExists: true),
                ]
                """
            }
        }
    }

    test("homo sapiens - vcf, ref, sites, map") {
        when {
            params {
                minimac4_args = "--chunk 1000000"
            }
            process {
                """
                input[0] = channel.of([
                    [id: "NA12878", chr: "chr22"],
                    file(params.modules_testdata_base_path + "genomics/homo_sapiens/illumina/vcf/NA12878.chr21_22.1X.glimpse2.vcf.gz",checkIfExists:true),
                    file(params.modules_testdata_base_path + "genomics/homo_sapiens/illumina/vcf/NA12878.chr21_22.1X.glimpse2.vcf.gz.csi",checkIfExists:true),
                    file(params.modules_testdata_base_path + "genomics/homo_sapiens/genome/genetic_map/genome.GRCh38.chr22.minimac.map", checkIfExists:true)
                ])
                .combine(MINIMAC4_COMPRESSREF.out.msav)
                .map{
                    meta, target_vcf, target_index, map, metaRef, ref -> [
                        meta, target_vcf, target_index, ref, map, "chr22"
                    ]
                }
                input[1] = true
                """
            }
        }

        then {
            assert process.success
            assert snapshot(sanitizeOutput(process.out, variantsMD5Keys: ["vcf", "sites"])).match()
        }

    }

    test("homo sapiens - vcf, ref, [], []") {
        when {
            params {
                minimac4_args = "--output-format vcf"
            }
            process {
                """
                input[0] = channel.of([
                    [id: "NA12878", chr: "chr22"],
                    file(params.modules_testdata_base_path + "genomics/homo_sapiens/illumina/vcf/NA12878.chr21_22.1X.glimpse2.vcf.gz",checkIfExists:true),
                    file(params.modules_testdata_base_path + "genomics/homo_sapiens/illumina/vcf/NA12878.chr21_22.1X.glimpse2.vcf.gz.csi",checkIfExists:true)
                ])
                .combine(MINIMAC4_COMPRESSREF.out.msav)
                .map{
                    meta, target_vcf, target_index, metaRef, ref -> [
                        meta, target_vcf, target_index, ref, [], []
                    ]
                }
                input[1] = true
                """
            }
        }

        then {
            assert process.success
            snapshot(sanitizeOutput(process.out, variantsMD5Keys: ["vcf", "sites"])).match()
        }

    }

    test("homo sapiens - vcf, ref, map - stub") {
        options "-stub"
        when {
            params {
                minimac4_args = "-O usav"
            }
            process {
                """
                input[0] = [
                    [id: "NA12878", chr: "chr22"],
                    file(params.modules_testdata_base_path + "genomics/homo_sapiens/illumina/vcf/NA12878.chr21_22.1X.glimpse2.vcf.gz",checkIfExists:true),
                    file(params.modules_testdata_base_path + "genomics/homo_sapiens/illumina/vcf/NA12878.chr21_22.1X.glimpse2.vcf.gz.csi",checkIfExists:true),
                    [], [], []
                ]
                input[1] = true
                """
            }
        }

        then {
            assert process.success
            assert snapshot(sanitizeOutput(process.out)).match()
        }

    }

}

